export function manualSalePrice(entry,item){if(!entry||!item)return 0;if(entry.uid){const rank={common:1,rare:2,uncommon:4,legendary:7,mythic:12}[entry.rarity]||1;return Math.max(1,Math.round((entry.tier||1)**2*rank*20));}return Math.max(1,Math.floor((item.cost||item.quest&&500||item.evolution&&300||item.craft&&25||1)*(item.junk?1:.5)));}
export function sellBagEntry(player,key,quantity,items){const index=player.bag.findIndex(e=>(e.uid||e.id)===key),entry=player.bag[index],item=items[entry?.id],qty=Number(quantity);if(!entry||!item||!Number.isInteger(qty)||qty<1||qty>(entry.uid?1:entry.qty))return {error:'出售數量不正確或物品已變更'};const gold=manualSalePrice(entry,item)*qty;if(entry.uid||qty===entry.qty)player.bag.splice(index,1);else entry.qty-=qty;player.gold+=gold;return {gold,qty,name:item.name};}
